#include "PlanetTerrain.h"
#include <stdexcept>
#include <cstdio>
#include <chrono>
#include <set>
#include <random>
static unsigned checks=0,failures=0;
void check(bool ok,const char* name){++checks;if(!ok){++failures;std::printf("FAIL %s\n",name);}}
int main(){using V=glm::dvec3;PlanetSettings config;std::string error;check(ValidatePlanetSettings(config,error),"default precision terrain settings valid");PlanetSurface sphere(config);
 double maxPosition=0,maxBoundary=0,maxMorph=0;unsigned fineLevel=22;
 for(unsigned face=0;face<6;++face){const auto d=PlanetSurface::Direction(face,.125,-.25);const auto k=PlanetSurface::Locate(d,fineLevel);auto tile=BuildPlanetTile(sphere,k,16);auto mesh=tile.Mesh(1,1);check(mesh.vertices.size()==1920,"bounded nonindexed tile with skirts");for(size_t i=0;i<tile.points.size();++i){const V reconstructed=tile.origin+V(glm::vec3(tile.points[i]-tile.origin));maxPosition=std::max(maxPosition,glm::length(reconstructed-tile.points[i]));}auto parent=tile.Mesh(0);for(size_t i=0;i<parent.vertices.size();++i)check(std::isfinite(parent.vertices[i].position.x),"morph parent finite");
  for(unsigned y=0;y<=16;++y){auto a=sphere.GridPoint(k,16,y,16);auto next=k;next.x++;if(next.x<(1u<<fineLevel))maxBoundary=std::max(maxBoundary,glm::length(a-sphere.GridPoint(next,0,y,16)));}
  for(unsigned y=0;y<=16;++y)for(unsigned x=0;x<=16;++x){const auto p=tile.points[size_t(y)*17+x];const auto d0=glm::normalize(p-config.center);const auto ref=PlanetTrianglePoint(sphere,k.Parent(),d0,16);maxMorph=std::max(maxMorph,glm::length(ref-tile.parentPoints[size_t(y)*17+x]));}
 }
 check(maxPosition<1e-5,"Earth radius tile-local float reconstruction below ten micrometres");check(maxBoundary<1e-8,"adjacent tile vertices agree in double");check(maxMorph<1e-8,"child starts on exact parent triangle plane");
 // Across cube faces: independently select the neighbouring face's grid at
 // the same rational edge location, not two calls through one face.
 for(unsigned face=0;face<6;++face)for(int edge=0;edge<4;++edge)for(unsigned i=0;i<=32;++i){const double t=2.*i/32-1;const double u=edge<2?(edge==0?-1.:1.):t,v=edge>=2?(edge==2?-1.:1.):t;auto a=PlanetSurface::Direction(face,u,v);double minimum=100;
  for(unsigned other=0;other<6;++other)if(other!=face){try{auto uv=PlanetSurface::FaceCoordinates(other,a);if(std::abs(uv.x)<=1+1e-12&&std::abs(uv.y)<=1+1e-12)minimum=std::min(minimum,glm::length(sphere.Point(a)-sphere.Point(PlanetSurface::Direction(other,uv.x,uv.y))));}catch(const std::invalid_argument&){} }
  check(minimum<2e-8,"independent cube-face edge sampling agrees below twenty nanometres");}
 auto detail=config;detail.bands={{{.025},{2.1,0,1.7}}};PlanetSurface detailed(detail);auto p=V(1,detail.radius,1);auto sample=detailed.Sample(p);const auto modelDirection=glm::normalize(p);check(std::abs(sample.height-detailed.HeightAt(modelDirection))<1e-12,"fine elevation remains binary64 independent of base radius");check(glm::length(sample.normal-modelDirection)>.001,"centimetre detail changes physical normal");check(std::abs(glm::length(sample.normal)-1)<1e-12,"normal remains normalized");
 auto shifted=detail;shifted.center={1e12,-1e12,1e12};shifted.rotation=glm::angleAxis(.7,glm::normalize(V(1,2,3)));PlanetSurface moved(shifted);auto rotated=moved.Sample(shifted.center+shifted.rotation*p);check(glm::length(rotated.point-(shifted.center+shifted.rotation*sample.point))<.001,"rotated terrain at trillion-metre absolute offset preserves submillimetre location");check(glm::length(rotated.normal-shifted.rotation*sample.normal)<.001,"normal rotates equivalently at distant absolute origin");
 PlanetHeightPatch patch;patch.direction={0,1,0};patch.extent=4;patch.resolution=3;patch.heights.assign(9,0);patch.heights[4]=.03;auto authored=config;authored.patches={patch};PlanetSurface raster(authored);check(std::abs(raster.HeightAt({0,1,0})-.03)<1e-12,"external authored raster produces three-centimetre feature");check(raster.HeightAt({1,0,0})==0,"patch cannot contaminate remote hemisphere");check(std::abs(raster.HeightAt(glm::normalize(V(4,config.radius,0))))<1e-12,"patch blends to zero at finite extent");
 auto json=EncodePlanetSettings(authored);PlanetSettings roundtrip;check(DecodePlanetSettings(json,roundtrip,error)&&EncodePlanetSettings(roundtrip)==json,"full descriptor roundtrip");check(!DecodePlanetSettings("{\"version\":2}",roundtrip,error),"unknown version rejects");check(!DecodePlanetSettings("{\"version\":1,\"maxTiles\":5}",roundtrip,error),"budget cannot remove six coverage roots");check(!DecodePlanetSettings("{\"version\":1,\"surprise\":3}",roundtrip,error),"unknown fields reject");
 auto invalid=config;invalid.maxResident=invalid.maxTiles;check(!ValidatePlanetSettings(invalid,error),"resident budget includes reverse-transition parent cache");invalid=config;invalid.maxTiles=4096;invalid.maxResident=8192;invalid.segments=64;check(!ValidatePlanetSettings(invalid,error),"CPU/GPU byte estimate rejects excessive geometry despite valid counts");PlanetSurface centimetres(config,[](V){return .03;},.03,0);check(std::abs(glm::length(centimetres.Point({0,1,0}))-config.radius-.03)<1e-8&&double(float(config.radius+.03)-float(config.radius))==0,"binary64 radial positioning preserves detail lost by legacy float radius addition");
 bool threw=false;try{PlanetSurface bad(config,[](V){return 2.;},1,1);bad.Point({0,1,0});}catch(const std::exception&){threw=true;}check(threw,"provider violating certified height fails explicitly");
 size_t most=0;double time=0;for(auto altitude:{1.,100.,10000.,1e6,1e7}){auto start=std::chrono::steady_clock::now();auto selected=SelectPlanetTiles(detailed,{0,config.radius+altitude,0},1.,1080);time+=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();most=std::max(most,selected.leaves.size());check(selected.leaves.size()<=config.maxTiles,"view-dependent leaf count obeys hard bound");
  for(unsigned face=0;face<6;++face){double area=0;for(auto k:selected.leaves)if(k.face==face)area+=std::ldexp(1.,-2*int(k.level));check(std::abs(area-1)<1e-12,"quadtree covers complete face without missing patches");}
  auto repeat=SelectPlanetTiles(detailed,{0,config.radius+altitude,0},1.,1080);check(repeat.leaves==selected.leaves,"same view gives deterministic selection");}
 std::printf("MEASURE tile_float_reconstruction_m=%.12g same_face_seam_m=%.12g parent_morph_m=%.12g max_leaves=%zu five_view_selection_ms=%.6f\n",maxPosition,maxBoundary,maxMorph,most,time);std::printf("SUMMARY %u checks %u failures\n",checks,failures);return failures?1:0;}
